<template><q-page class="q-pa-lg"><div class="row justify-between items-center q-mb-lg"><div><h1 class="page-title">Deliveries</h1><p class="page-subtitle">Pending → Preparing → Out for Delivery → Delivered</p></div><q-btn color="primary" icon="add" label="Schedule delivery" @click="open"/></div><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><q-select v-model="status" outlined clearable dense label="Filter status" :options="statuses" class="q-mb-md" style="max-width:300px" @update:model-value="page=1;load()"/>
<q-table :rows="rows" :columns="columns" row-key="id" :loading="loading" flat bordered hide-pagination :pagination="{rowsPerPage:0}"><template #body-cell-status="p"><q-td :props="p"><q-badge :color="p.row.status==='Delivered'?'teal':p.row.status==='Cancelled'?'grey':'primary'">{{p.row.status}}</q-badge></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn v-for="s in next[p.row.status]||[]" :key="s" flat dense :label="s==='Cancelled'?'Cancel':`Mark ${s}`" :color="s==='Cancelled'?'negative':'primary'" :disable="updating===p.row.id" @click="transition(p.row,s)"/></q-td></template></q-table><div class="row justify-end q-mt-md"><q-pagination v-model="page" :max="last" :max-pages="5" direction-links @update:model-value="load"/></div>
<q-dialog v-model="dialog" persistent><q-card style="width:520px;max-width:95vw"><q-card-section class="text-h6">Schedule delivery</q-card-section><q-form @submit="save"><q-card-section class="q-gutter-md"><q-select v-model="order" outlined use-input input-debounce="300" label="Find completed sale by receipt / customer" :options="orders" :option-label="orderLabel" @filter="findOrders" @update:model-value="choose" :rules="[v=>!!v||'Select a sale']"><template #no-option><q-item><q-item-section>No matching completed sales.</q-item-section></q-item></template></q-select><q-input v-model.trim="form.recipient_name" outlined label="Recipient" maxlength="255" :rules="[v=>!!v||'Required']"/><q-input v-model.trim="form.phone" outlined label="Phone" maxlength="40"/><q-input v-model.trim="form.address" outlined type="textarea" label="Delivery address" maxlength="2000" :rules="[v=>!!v||'Required']"/><q-input v-model="form.scheduled_at" outlined type="datetime-local" label="Scheduled time (Asia/Manila)" stack-label/><q-input v-model="form.notes" outlined label="Notes" maxlength="2000"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="saving" v-close-popup/><q-btn color="primary" type="submit" label="Schedule delivery" :loading="saving"/></q-card-actions></q-form></q-card></q-dialog>
</q-page></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{useQuasar}from'quasar';import api,{errorMessage}from'../services/api';import{dateTime}from'../services/format'
const q=useQuasar(),rows=ref<any[]>([]),orders=ref<any[]>([]),order=ref<any>(null),loading=ref(false),saving=ref(false),error=ref(''),status=ref<string|null>(null),page=ref(1),last=ref(1),dialog=ref(false),updating=ref<number|null>(null)
const blank=()=>({recipient_name:'',phone:'',address:'',scheduled_at:'',notes:''}),form=ref(blank()),statuses=['Pending','Preparing','Out for Delivery','Delivered','Cancelled'],next:Record<string,string[]>={'Pending':['Preparing','Cancelled'],'Preparing':['Out for Delivery','Cancelled'],'Out for Delivery':['Delivered']}
const orderLabel=(o:any)=>o?`${o.receipt_number||`Legacy #${o.id}`} · ${o.customer_name}`:''
const columns=[{name:'receipt',label:'Sale',field:(r:any)=>r.order?.receipt_number||`Legacy #${r.order_id||'—'}`,align:'left' as const},{name:'recipient_name',label:'Recipient',field:'recipient_name',align:'left' as const},{name:'phone',label:'Phone',field:'phone',align:'left' as const},{name:'address',label:'Address',field:'address',align:'left' as const},{name:'scheduled_at',label:'Scheduled',field:(r:any)=>dateTime(r.scheduled_at),align:'left' as const},{name:'status',label:'Status',field:'status',align:'left' as const},{name:'actions',label:'Next step',field:'id',align:'right' as const}]
async function load(){loading.value=true;error.value='';try{const{data}=await api.get('/deliveries',{params:{page:page.value,status:status.value}});rows.value=data.data;last.value=data.last_page}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function findOrders(v:string,update:(f:()=>void)=>void){try{const{data}=await api.get('/orders',{params:{search:v,status:'Completed'}});update(()=>{orders.value=data.data})}catch(e){update(()=>{orders.value=[]});q.notify({type:'negative',message:errorMessage(e)})}}
function choose(o:any){form.value.recipient_name=o?.customer_name||'';form.value.phone=o?.customer?.phone||'';form.value.address=o?.customer?.address||''}
function open(){order.value=null;form.value=blank();dialog.value=true}
async function save(){if(saving.value||!order.value)return;saving.value=true;try{await api.post('/deliveries',{...form.value,scheduled_at:form.value.scheduled_at||null,order_id:order.value.id});dialog.value=false;page.value=1;await load();q.notify({type:'positive',message:'Delivery scheduled.'})}catch(e){q.notify({type:'negative',message:errorMessage(e)})}finally{saving.value=false}}
function transition(row:any,s:string){q.dialog({title:`Mark ${s}?`,message:`Update delivery for ${row.recipient_name}?`,cancel:true}).onOk(async()=>{updating.value=row.id;try{await api.patch(`/deliveries/${row.id}`,{status:s});await load()}catch(e){q.notify({type:'negative',message:errorMessage(e)})}finally{updating.value=null}})}onMounted(load)
</script>
